nextflow_process {

    name "Test Process PBBAM_PBMERGE"
    script "../main.nf"
    process "PBBAM_PBMERGE"

    tag "modules"
    tag "modules_nfcore"
    tag "pbbam"
    tag "pbbam/pbmerge"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('bam') ]
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated. Please use nf-core/modules/pbtk/pbmerge") }
            )
        }
    }
}
